"""Apply a JSON Patch (RFC 6902) to a JSON document. See task.md."""

from __future__ import annotations

import re
from typing import Any


class PatchError(ValueError):
    """Raised when a patch is malformed or cannot be applied."""


_INDEX = re.compile(r"0|[1-9][0-9]*")
_MISSING = object()


def _copy(v: Any) -> Any:
    if isinstance(v, dict):
        return {k: _copy(x) for k, x in v.items()}
    if isinstance(v, list):
        return [_copy(x) for x in v]
    return v


def _parse(ptr: Any) -> list[str]:
    if not isinstance(ptr, str):
        raise PatchError("pointer must be a string")
    if ptr == "":
        return []
    if not ptr.startswith("/"):
        raise PatchError(f"invalid pointer {ptr!r}")
    tokens = []
    for raw in ptr[1:].split("/"):
        i = raw.find("~")
        while i != -1:
            if raw[i + 1 : i + 2] not in ("0", "1"):
                raise PatchError(f"invalid escape in pointer {ptr!r}")
            i = raw.find("~", i + 2)
        tokens.append(raw.replace("~1", "/").replace("~0", "~"))
    return tokens


def _index(token: str, size: int, allow_end: bool) -> int:
    if not _INDEX.fullmatch(token):
        raise PatchError(f"invalid array index {token!r}")
    n = int(token)
    if n > size or (n == size and not allow_end):
        raise PatchError(f"array index {token} out of range")
    return n


def _parent(doc: Any, tokens: list[str]) -> Any:
    cur = doc
    for t in tokens[:-1]:
        if isinstance(cur, dict):
            if t not in cur:
                raise PatchError(f"missing member {t!r}")
            cur = cur[t]
        elif isinstance(cur, list):
            cur = cur[_index(t, len(cur), False)]
        else:
            raise PatchError("cannot descend into a scalar")
    return cur


def _get(doc: Any, tokens: list[str]) -> Any:
    if not tokens:
        return doc
    parent = _parent(doc, tokens)
    t = tokens[-1]
    if isinstance(parent, dict):
        if t not in parent:
            raise PatchError(f"missing member {t!r}")
        return parent[t]
    if isinstance(parent, list):
        return parent[_index(t, len(parent), False)]
    raise PatchError("cannot descend into a scalar")


def _add(doc: Any, tokens: list[str], value: Any) -> Any:
    if not tokens:
        return value
    parent = _parent(doc, tokens)
    t = tokens[-1]
    if isinstance(parent, dict):
        parent[t] = value
    elif isinstance(parent, list):
        if t == "-":
            parent.append(value)
        else:
            parent.insert(_index(t, len(parent), True), value)
    else:
        raise PatchError("cannot descend into a scalar")
    return doc


def _remove(doc: Any, tokens: list[str]) -> Any:
    if not tokens:
        raise PatchError("cannot remove the whole document")
    parent = _parent(doc, tokens)
    t = tokens[-1]
    if isinstance(parent, dict):
        if t not in parent:
            raise PatchError(f"missing member {t!r}")
        return parent.pop(t)
    if isinstance(parent, list):
        return parent.pop(_index(t, len(parent), False))
    raise PatchError("cannot descend into a scalar")


def _is_num(v: Any) -> bool:
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _equal(a: Any, b: Any) -> bool:
    if isinstance(a, dict):
        return (
            isinstance(b, dict)
            and a.keys() == b.keys()
            and all(_equal(a[k], b[k]) for k in a)
        )
    if isinstance(a, list):
        return (
            isinstance(b, list)
            and len(a) == len(b)
            and all(_equal(x, y) for x, y in zip(a, b))
        )
    if _is_num(a):
        return _is_num(b) and a == b
    if isinstance(a, bool) or a is None:
        return a is b
    return isinstance(a, str) and isinstance(b, str) and a == b


def apply(document: Any, patch: list[dict]) -> Any:
    """Return the result of applying `patch` to `document`."""
    if not isinstance(patch, list):
        raise PatchError("patch must be a list")
    doc = _copy(document)
    for opobj in patch:
        if not isinstance(opobj, dict):
            raise PatchError("operation must be an object")
        op = opobj.get("op")
        if not isinstance(op, str) or op not in (
            "add", "remove", "replace", "move", "copy", "test"
        ):
            raise PatchError(f"invalid op {op!r}")
        path = _parse(opobj.get("path"))
        value = _MISSING
        if op in ("add", "replace", "test"):
            value = opobj.get("value", _MISSING)
            if value is _MISSING:
                raise PatchError("missing value")
        if op in ("move", "copy"):
            if "from" not in opobj:
                raise PatchError("missing from")
            src = _parse(opobj["from"])

        if op == "add":
            doc = _add(doc, path, _copy(value))
        elif op == "remove":
            _remove(doc, path)
        elif op == "replace":
            _get(doc, path)
            if not path:
                doc = _copy(value)
            else:
                parent = _parent(doc, path)
                if isinstance(parent, dict):
                    parent[path[-1]] = _copy(value)
                else:
                    parent[_index(path[-1], len(parent), False)] = _copy(value)
        elif op == "move":
            _get(doc, src)
            if src == path:
                continue
            if path[: len(src)] == src and len(path) > len(src):
                raise PatchError("cannot move a value into its own child")
            doc = _add(doc, path, _remove(doc, src))
        elif op == "copy":
            doc = _add(doc, path, _copy(_get(doc, src)))
        else:
            if not _equal(_get(doc, path), value):
                raise PatchError("test failed")
    return doc
